def scan(name,text=""):
    im=Image.open(f"scans/{name}.png").convert("RGB")
    im=im.resize((2880,int(664*2880/1108)),Image.LANCZOS).crop((0,0,2880,1620))
    im.info["scan"]=True;im.info["strip"]=text
    return im
